//! The inverse transformation of a LutMap matches C's (lutmap.c
//! `Transform`) exactly, for tables with bad entries, flat runs, either
//! direction and both interpolation methods, at the table values, between
//! them and beyond both ends.
//!
//! `lutmap_inverse_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/lutmap_inverse_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "lutmap_inverse_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::mappings::{LutInterp, LutMap, Mapping};

#[test]
fn inverse_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(name, lut, start, inc, nearest, pairs) in cases::CASES {
        let mut map = LutMap::new(lut, start, inc).unwrap();
        if nearest {
            map.set_interp(LutInterp::Nearest);
        }
        let rows: Vec<[f64; 1]> = pairs.iter().map(|&(y, _)| [y]).collect();
        let out = map.transform(&PointSet::from_rows(rows), false).unwrap();
        for (i, &(y, want)) in pairs.iter().enumerate() {
            let got = out.point(i)[0];
            if got.to_bits() != want.to_bits() {
                failures.push(format!(
                    "{name}: inverse of {y:e} is {got:e}, C gives {want:e}"
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
